/**
 * How Folding fan on a casket (`hako-ogi`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/hako-ogi";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Strike a broad fan face above a six-sided casket with a curled pattern. Rule the ribs and guard across the lid. Carry each hanging cord into the loop above and the knotted pendant below.","ja":"巻き模様のある六角形の筥の上に地紙を打ち、ふたに重なるように骨と親骨を引きます。両側の紐は上の輪から下の結び房までつなぎます。"};

export default construction;
export { construction, description };
